const b=$json.body??$json;
const d=b.data??b;
const key=d.key??{};
const fromMe=Boolean(key.fromMe??d.fromMe);
const remote=String(key.remoteJid??d.remoteJid??b.sender??'');
if(fromMe) return [];
if(remote.endsWith('@g.us')) return [];
const phone=remote.replace(/@s\.whatsapp\.net|@c\.us/g,'').replace(/\D/g,'');
if(!phone) return [];
const msgId=String(key.id??d.messageId??b.id??'');
const m=d.message??b.message??{};
const text=String(
  m.conversation ??
  m.extendedTextMessage?.text ??
  m.imageMessage?.caption ??
  m.videoMessage?.caption ??
  d.text ??
  b.text ??
  ''
).trim();
if(!text) return [];
const store=$getWorkflowStaticData('global');
store.msgIds=store.msgIds||{};
if(msgId && store.msgIds[msgId]) return [];
if(msgId) store.msgIds[msgId]=Date.now();
const cutoff=Date.now()-7*24*60*60*1000;
for(const [k,v] of Object.entries(store.msgIds)){ if(v<cutoff) delete store.msgIds[k]; }
store.contacts=store.contacts||{};
const c=store.contacts[phone]||{history:[],do_not_contact:false};
const low=text.toLowerCase();
const optout=/\b(sair|pare|parar|remover|não quero|nao quero|cancelar)\b/.test(low);
if(optout) c.do_not_contact=true;
const history=(c.history||[]).slice(-8);
store.contacts[phone]=c;
return [{json:{
  phone,
  name:String(d.pushName??b.pushName??''),
  text,
  message_id:msgId,
  optout,
  do_not_contact:Boolean(c.do_not_contact),
  history,
  received_at:new Date().toISOString()
}}];

