const store=$getWorkflowStaticData('global');
store.leads=store.leads||{};
store.outreachLog=store.outreachLog||[];
const already=new Set(store.outreachLog.map(x=>String(x.lead_id||x.phone||x.email||'')));
const values=Object.values(store.leads)
  .filter(x=>x && x.do_not_contact!==true && x.status!=='cliente')
  .filter(x=>!already.has(String(x.lead_id||x.phone||x.email||'')))
  .sort((a,b)=>(b.score||0)-(a.score||0))
  .slice(0,100);
return values.map(x=>({json:x}));

const arr=Array.isArray($json)?$json:($json.items??[$json]);
const seen=new Set();
return arr.filter(x=>{
 const k=String(x.phone||x.email||x.domain||x.company||'').trim().toLowerCase();
 if(!k||seen.has(k)||x.do_not_contact===true||x.status==='cliente') return false;
 seen.add(k); return true;
}).map(x=>({json:{...x,research_status:'prequalificado',researched_at:new Date().toISOString()}}));

const store=$getWorkflowStaticData('global');
store.outreachQueue=store.outreachQueue||[];
const items=$input.all().map(i=>i.json);
const existing=new Set(store.outreachQueue.map(x=>String(x.lead_id||x.phone||x.email||'')));
for(const x of items){
  const key=String(x.lead_id||x.phone||x.email||'');
  if(!key||existing.has(key)||x.do_not_contact===true) continue;
  store.outreachQueue.push({...x,queued_at:new Date().toISOString(),status:'queued'});
  existing.add(key);
}
return [{json:{queued:items.length,total_queue:store.outreachQueue.length}}];

const store=$getWorkflowStaticData('global');
store.outreachQueue=store.outreachQueue||[];
const batch=store.outreachQueue
  .filter(x=>x.status==='queued' && x.do_not_contact!==true)
  .slice(0,10);
return batch.map(x=>({json:x}));

const arr=Array.isArray($json)?$json:($json.items??[$json]);
const now=new Date(new Date().toLocaleString('en-US',{timeZone:'America/Sao_Paulo'}));
const hour=now.getHours();
const allowed=hour>=9&&hour<19;
return arr.filter(x=>{
 if(x.do_not_contact===true||x.duplicate===true||!allowed) return false;
 if((x.channel||'').toLowerCase()==='whatsapp' && x.opt_in_whatsapp!==true) return false;
 return true;
}).map(x=>({json:{...x,send_allowed:true,checked_at:new Date().toISOString()}}));

