if(row){ row.status='sent'; row.sent_at=new Date().toISOString(); }
store.outreachLog.push({...sent,logged_at:new Date().toISOString()});
return [{json:{ok:true,key,total_sent:store.outreachLog.length}}];

const store=$getWorkflowStaticData('global');
