const store=$getWorkflowStaticData('global');
store.clients=store.clients||{};
const rows=Object.values(store.clients);
return rows.map(c=>({json:{
  ...c,
  days_since_contact:c.last_contact_at?Math.floor((Date.now()-Date.parse(c.last_contact_at))/86400000):999,
  payment_overdue:Boolean(c.payment_overdue),
  performance_alerts:Number(c.performance_alerts||0),
  open_support_issues:Number(c.open_support_issues||0),
  nps:c.nps??null
}}));

const arr=Array.isArray($json)?$json:($json.items??[$json]);
return arr.map(c=>{
 let risk=0;
 if((c.days_since_contact||0)>7)risk+=20;
 if(c.payment_overdue===true)risk+=30;
 if((c.performance_alerts||0)>2)risk+=20;
 if((c.open_support_issues||0)>0)risk+=15;
 if(c.nps!=null&&c.nps<7)risk+=20;
 return {json:{...c,risk_score:Math.min(100,risk),risk_level:risk>=60?'alto':risk>=30?'medio':'baixo'}};
});

const store=$getWorkflowStaticData('global');
store.leads=store.leads||{};
store.outreachLog=store.outreachLog||[];
store.meetings=store.meetings||[];
store.proposals=store.proposals||[];
store.clients=store.clients||{};
store.sales=store.sales||[];
const start=new Date(); start.setHours(0,0,0,0);
const today=t=>{const d=Date.parse(t||'');return Number.isFinite(d)&&d>=start.getTime();};
const leads=Object.values(store.leads);
const sales=store.sales;
return [{json:{
  new_leads:leads.filter(x=>today(x.created_at||x.updated_at)).length,
  hot_leads:leads.filter(x=>(x.score||0)>=70).length,
  outreach_sent:store.outreachLog.filter(x=>today(x.logged_at||x.sent_at)).length,
  replies:leads.filter(x=>today(x.last_reply_at)).length,
  meetings:store.meetings.filter(x=>today(x.created_at||x.start)).length,
  proposals:store.proposals.filter(x=>today(x.generated_at||x.created_at)).length,
  sales:sales.filter(x=>today(x.closed_at||x.created_at)).length,
  closed_revenue:sales.filter(x=>today(x.closed_at||x.created_at)).reduce((a,b)=>a+Number(b.value||0),0),
  mrr:Object.values(store.clients).reduce((a,b)=>a+Number(b.mrr||0),0),
  clients_at_risk:Object.values(store.clients).filter(x=>x.risk_level==='alto').length,
  automation_errors:Number(store.automation_errors||0)
}}];

